"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[5563],{5563(e,n,r){r.d(n,{content:()=>d,description:()=>s,keywords:()=>a,title:()=>t});r(5043);var i=r(579);const t="Ihre VR-Brillen an der Schule haben keine Roadmap mehr",s="Meta hat den Verkauf kommerzieller Quest-Brillen im Februar 2026 eingestellt, der Support endet im Januar 2030. Was Schulen mit VR-Flotten jetzt tun sollten.",a=["Meta Quest Schule","Meta for Education","Horizon Managed Services","Virtual Reality im Unterricht","VR-Brillen f\xfcr Schulen","virtuelles Labor","ger\xe4teunabh\xe4ngige virtuelle Labore","VR-Beschaffung Schule"],d=(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)("p",{children:["Am 20. Februar 2026 hat Meta den Verkauf von Horizon Managed Services und der kommerziellen Versionen seiner Quest-Brillen eingestellt (",(0,i.jsx)("a",{href:"https://work.meta.com/help/1964851097790493/",target:"_blank",rel:"noopener noreferrer",children:"Meta, 2026"}),"). Es gab keine Keynote und keine Pressetour. Die \xc4nderung erschien in einem Artikel im Hilfebereich, und sofern die IT-Verantwortlichen Ihrer Schule die Nachrichtenlage zum Ger\xe4temanagement nicht sehr genau verfolgen, haben Sie davon wom\xf6glich gar nichts mitbekommen. F\xfcr jede Schule, die in eine Flotte von Quest-Brillen investiert hat, ist es dennoch eine der folgenreichsten Bildungstechnologie-Meldungen des Jahres, denn sie setzt der Plattform, auf der diese Brillen laufen, ein Enddatum."]}),(0,i.jsx)("p",{children:"Wir entwickeln Software f\xfcr virtuelle Labore, die auf VR-Brillen l\xe4uft, und wir halten VR nach wie vor f\xfcr einen bemerkenswerten Weg, praktische Naturwissenschaft zu betreiben. Genau deshalb verdient diese Ank\xfcndigung eine n\xfcchterne Betrachtung statt Panik oder Abwinken. Sie stellt nicht infrage, ob VR in die Schule geh\xf6rt. Sie ver\xe4ndert, wie Schulen \xfcber das Verh\xe4ltnis zwischen der gekauften Hardware und der Lernsoftware nachdenken sollten, auf die sie sich verlassen."}),(0,i.jsx)("h2",{children:"Was hat Meta tats\xe4chlich angek\xfcndigt?"}),(0,i.jsxs)("p",{children:["Drei Dinge geschahen gleichzeitig. Erstens ist Horizon Managed Services, das System, mit dem Schulen und Unternehmen Flotten von Quest-Brillen registrieren, verwalten und absichern, nicht mehr k\xe4uflich zu erwerben, und bestehende Lizenzen wurden kostenlos (",(0,i.jsx)("a",{href:"https://help.managexr.com/en/articles/13394353-update-meta-horizon-managed-services-will-be-free-starting-feb-20-2026",target:"_blank",rel:"noopener noreferrer",children:"ManageXR, 2026"}),"). Zweitens sind die kommerziellen SKUs der Meta Quest, also die Varianten mit Gesch\xe4fts- statt Verbraucherbedingungen, nicht mehr im Verkauf. Drittens, und f\xfcr die Planung am wichtigsten, ist die gesamte Managed-Services-Plattform in den Wartungsmodus \xfcbergegangen. Meta sagt Fehlerbehebungen und Support f\xfcr bestehende Kunden bis zum ",(0,i.jsx)("strong",{children:"4. Januar 2030"})," zu, neue Funktionen wird es jedoch nicht geben, und Meta erkl\xe4rt selbst, dass \xfcber dieses Datum hinaus keine konkreten Zusagen zum Verhalten der Plattform m\xf6glich sind (",(0,i.jsx)("a",{href:"https://redboxvr.com/meta-horizon-managed-services-update/",target:"_blank",rel:"noopener noreferrer",children:"RedboxVR, 2026"}),")."]}),(0,i.jsx)("p",{children:"Nichts davon schaltet irgendjemandem die Brillen ab. Bereits ausgerollte Ger\xe4te funktionieren weiter, bestehende Registrierungen bleiben aktiv, und die Verwaltungsebene ist jetzt kostenlos, was kurzfristig eine echte Ersparnis bedeutet. Beschaffungstechnisch hat die Plattform jedoch nun einen ver\xf6ffentlichten Support-Horizont und keinen angek\xfcndigten Nachfolger. F\xfcr diese Kombination gibt es in der IT-Planung einen Begriff: eine Support-Klippe."}),(0,i.jsx)("h2",{children:"Warum betrifft das Schulen besonders?"}),(0,i.jsxs)("p",{children:["Meta hat die vergangenen zwei Jahre gezielt um den Bildungsbereich geworben. Meta for Education brachte Schulen und Hochschulen verwaltete Quest-Rollouts, Content-Partnerschaften f\xfcr den Unterricht und Werkzeuge zur Klassenraumverwaltung (",(0,i.jsx)("a",{href:"https://www.meta.com/blog/meta-for-education-quest-classroom-educators-vr-mixed-reality/",target:"_blank",rel:"noopener noreferrer",children:"Meta, 2025"}),"). Schulen, die dieser Einladung gefolgt sind, haben mit den verf\xfcgbaren Informationen eine vern\xfcnftige Entscheidung getroffen. Das Problem ist, dass schulische Beschaffungszyklen lang sind. Eine weiterf\xfchrende Schule, die 2025 einen Klassensatz Brillen gekauft hat, plant \xfcblicherweise mit f\xfcnf bis sieben Jahren Nutzungsdauer, und dieser Zeitraum reicht nun \xfcber den Punkt hinaus, bis zu dem Meta die Verwaltung dieser Ger\xe4te zu unterst\xfctzen zusagt."]}),(0,i.jsx)("p",{children:"Schulen stehen zudem vor einer Einschr\xe4nkung, die Unternehmen nicht kennen. Ein Unternehmen kann drei\xdfig Brillen an einem Wochenende neu aufsetzen und die St\xf6rung verkraften. Eine Schule, die VR \xfcber einen ganzen Stundenplan hinweg einsetzt, mit Ger\xe4ten, die zwischen Klassen geteilt und von einer einzigen \xfcberlasteten Fachkraft betreut werden, kann das nicht. Ger\xe4temanagement ist im Klassenzimmer kein optionales Extra. Es ist der Unterschied zwischen einer Stunde, die p\xfcnktlich beginnt, und drei\xdfig Jugendlichen mit ungesicherten Consumer-Ger\xe4ten in der Hand. Deshalb wiegt der stille R\xfcckzug der kommerziellen Plattform f\xfcr Schulen schwerer, als die weiterhin erh\xe4ltlichen Consumer-Brillen vermuten lassen."}),(0,i.jsx)("h2",{children:"Ist VR in der Bildung damit vorbei?"}),(0,i.jsx)("p",{children:"Nein, und es lohnt sich, genau zu sagen, warum. Die Didaktik hat sich nicht ge\xe4ndert. Die Belege daf\xfcr, dass gut gestaltetes immersives Praxislernen den Transfer motorischer Fertigkeiten und das Engagement f\xf6rdert, sind heute dieselben wie im Januar. Ver\xe4ndert hat sich Kommerzielles, nicht P\xe4dagogisches: Ein gro\xdfer Hardware-Anbieter hat den institutionellen Markt zur\xfcckgestuft. Dieses Muster hat die Branche schon einmal gesehen. Anfang 2026 haben wir \xfcber den breiteren \u201eVR-Winter\u201c geschrieben, das Abk\xfchlen der Plattforminvestitionen nach dem Metaverse-Boom, und schon damals argumentiert, dass die robuste Position f\xfcr Schulen Software ist, die nicht davon abh\xe4ngt, dass ein bestimmtes Ger\xe4t die Marktbereinigung \xfcbersteht. Diese Ank\xfcndigung ist genau dieses Argument, p\xfcnktlich eingetroffen."}),(0,i.jsx)("p",{children:"Ebenso wichtig ist, was nicht zur\xfcckgezogen wurde. Consumer-Quest-Ger\xe4te bleiben im Verkauf, Drittanbieter f\xfcr Ger\xe4temanagement betreuen Quest-Flotten weiterhin, und andere Brillenhersteller bedienen den Bildungsmarkt nach wie vor. Der Markt konsolidiert sich, er verschwindet nicht. Aber Konsolidierung ist genau die Lage, in der es riskant wird, einen naturwissenschaftlichen Lehrplan auf die Roadmap eines einzigen Herstellers zu setzen, denn \xfcber diese Roadmap d\xfcrfen Sie nicht mitentscheiden."}),(0,i.jsx)("h2",{children:"Was sollten Schulen mit Quest-Flotten jetzt tun?"}),(0,i.jsx)("p",{children:"Erstens: Mustern Sie nichts aus. Ihre Brillen funktionieren, die Verwaltungsebene ist jetzt kostenlos, und Sie haben dreieinhalb Jahre zugesagten Support. Funktionierende Hardware aus Panik zu ersetzen, w\xe4re verschwendetes Geld ohne p\xe4dagogischen Gewinn. Nutzen Sie die kostenfreie Phase zu Ihrem Vorteil."}),(0,i.jsx)("p",{children:"Zweitens: Nehmen Sie das Datum 2030 jetzt in Ihre Schulentwicklungsplanung auf, solange es eine Planungsfrage und kein Notfall ist. Gut durch diese Situation kommen die Schulen, die den Januar 2030 so behandeln wie eine Heizungsanlage am Ende ihrer Lebensdauer: ein bekanntes Datum, \xfcber mehrere Jahre eingeplant, mit in Ruhe gepr\xfcften Optionen."}),(0,i.jsxs)("p",{children:["Drittens, und am wichtigsten: Pr\xfcfen Sie Ihre Software, nicht nur Ihre Hardware. Stellen Sie zu jeder VR-Anwendung, auf die sich Ihre Lehrkr\xe4fte st\xfctzen, eine einzige Frage: ",(0,i.jsx)("strong",{children:"W\xfcrde das Lernen \xfcberleben, wenn diese Brillen morgen verschw\xe4nden?"})," Existiert eine Anwendung nur auf einer Plattform, lautet die Antwort Nein, und jede darauf aufgebaute Unterrichtsplanung erbt das Ablaufdatum der Hardware. L\xe4uft die Anwendung auf den Ger\xe4ten, die Sie ohnehin in gro\xdfer Zahl besitzen, lautet die Antwort Ja, und die Brillen werden zu dem, was sie immer h\xe4tten sein sollen: eine Bereicherung, keine Abh\xe4ngigkeit."]}),(0,i.jsx)("h2",{children:"Wie w\xe4hlt man Laborsoftware, die die Brille \xfcberdauert?"}),(0,i.jsx)("p",{children:"Das ist die Designfrage, um die herum wir WhimsyLabs von Anfang an aufgebaut haben. Unsere virtuellen Labore laufen im Browser auf den Chromebooks, PCs und Macs, die Schulen bereits besitzen, und dieselben Labore laufen in VR, wo Brillen vorhanden sind und die zus\xe4tzliche Immersion gew\xfcnscht ist. Es ist eine Plattform, ein Konto-System, eine Lehrplanzuordnung und ein Satz von Ergebnis-Dashboards, unabh\xe4ngig vom Ger\xe4t. Die vollst\xe4ndige Physiksimulation, die Sandbox-Freiheit, gefahrlos zu entwerfen und zu scheitern, und WhimsyCats Einsch\xe4tzung der Arbeitsweise jeder Sch\xfclerin und jedes Sch\xfclers verhalten sich am Trackpad genauso wie in der Brille, weil sie in der Simulation leben und nicht in der Hardware."}),(0,i.jsx)("p",{children:"F\xfcr eine Schule mit Quest-Flotte ver\xe4ndert diese Architektur die Bedeutung der 2030-Frage. Das VR-Erlebnis funktioniert so lange, wie die Brillen es tun, und wenn die Flotte irgendwann altersbedingt ausscheidet, laufen die Labore, die Lernstandsdaten und die Unterrichtsplanungen der Lehrkr\xe4fte unangetastet auf den Ger\xe4ten weiter, die die Schule als N\xe4chstes einsetzt, seien es Brillen eines anderen Herstellers oder der Chromebook-Wagen, der nie verschwunden ist. Praktischer Naturwissenschaftsunterricht sollte kein Ablaufdatum haben, das die Strategieabteilung eines Hardware-Herstellers festlegt, und mit einer ger\xe4teunabh\xe4ngigen Plattform hat er das auch nicht."}),(0,i.jsx)("h2",{children:"Die Hardware ist nicht die Investition"}),(0,i.jsx)("p",{children:"Die unbequeme Lehre aus der Februar-Ank\xfcndigung lautet: Schulen wurden dazu ermutigt, die Brillen als Investition und die Software als Zubeh\xf6r zu betrachten, obwohl der dauerhafte Wert genau umgekehrt verteilt ist. Brillen verlieren an Wert, gehen kaputt und verlieren nun offenkundig auch ihre Roadmap. Was sich \xfcber Jahre summiert, sind die Lerninhalte, die Beurteilungsdaten und die um eine Plattform herum aufgebaute Expertise der Lehrkr\xe4fte. Diese Werte sind sch\xfctzenswert, und der Weg, sie zu sch\xfctzen, besteht darin, sicherzustellen, dass sie nie von einem einzelnen St\xfcck Hardware abh\xe4ngen. Ob Ihre Schule je wieder eine Brille kauft oder nicht: Das ist das Beschaffungsprinzip, das man aus 2026 mitnehmen sollte. Kaufen Sie Lernen, das \xfcberall l\xe4uft, und lassen Sie die Hardware kommen und gehen."}),(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)("h2",{children:"Verwandte Artikel"}),(0,i.jsxs)("ul",{children:[(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/de/blog/vr-headsets-vs-chromebooks-cost-per-student",children:"VR-Brillen oder Chromebooks f\xfcr virtuelle Labore: Kostenguide 2026"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/de/blog/vr-winter-web-first-virtual-labs",children:"VR-Winter? Warum Web-First Labore die kluge Wahl sind"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/de/blog/how-to-choose-virtual-lab-software-school",children:"Virtuelle Laborsoftware f\xfcr Sekundarschulen: Ein Kaufratgeber"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/de/blog/virtual-labs-vs-physical-labs-cost-benefit-analysis",children:"Virtuelle vs. physische Labore: Kosten-Nutzen-Analyse"})})]})]}),(0,i.jsxs)("div",{className:"references-section",children:[(0,i.jsx)("h3",{children:"Quellen"}),(0,i.jsxs)("ul",{className:"references-list",children:[(0,i.jsxs)("li",{children:["Meta. (2026). Update to Meta Horizon managed services. Meta for Work Help Centre."," ",(0,i.jsx)("a",{href:"https://work.meta.com/help/1964851097790493/",target:"_blank",rel:"noopener noreferrer",children:"https://work.meta.com/help/1964851097790493/"})]},"ref-1"),(0,i.jsxs)("li",{children:["ManageXR. (2026). Update: Meta Horizon Managed Services will be free starting Feb 20, 2026."," ",(0,i.jsx)("a",{href:"https://help.managexr.com/en/articles/13394353-update-meta-horizon-managed-services-will-be-free-starting-feb-20-2026",target:"_blank",rel:"noopener noreferrer",children:"https://help.managexr.com/en/articles/13394353-update-meta-horizon-managed-services-will-be-free-starting-feb-20-2026"})]},"ref-2"),(0,i.jsxs)("li",{children:["RedboxVR. (2026). Meta Horizon Managed Services update."," ",(0,i.jsx)("a",{href:"https://redboxvr.com/meta-horizon-managed-services-update/",target:"_blank",rel:"noopener noreferrer",children:"https://redboxvr.com/meta-horizon-managed-services-update/"})]},"ref-3"),(0,i.jsxs)("li",{children:["Meta. (2025). Introducing Meta for Education: Quest for the classroom."," ",(0,i.jsx)("a",{href:"https://www.meta.com/blog/meta-for-education-quest-classroom-educators-vr-mixed-reality/",target:"_blank",rel:"noopener noreferrer",children:"https://www.meta.com/blog/meta-for-education-quest-classroom-educators-vr-mixed-reality/"})]},"ref-4")]})]})]})}}]);
